import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// [No external shape imports to ensure stability without @remotion/shapes dependency]

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CartoonFlagProps = Record<string, any>;

// Helper component for the Star
const StarIcon: React.FC<{ size: number; color: string }> = ({ size, color }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill={color}
    style={{ display: "block" }}
  >
    <path d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z" />
  </svg>
);

// Inner Content of the flag (Stripes + Blue Field + Stars)
const FlagGraphic: React.FC<{ width: number; height: number }> = ({ width, height }) => {
  const stripeHeight = height / 13;
  const blueWidth = width * 0.4;
  const blueHeight = stripeHeight * 7;

  // Generate 50 stars positions roughly
  const starRows = 9;
  const starCols = 11; // alternating 6 and 5
  const stars = [];

  const xStep = blueWidth / 12;
  const yStep = blueHeight / 10;

  for (let row = 0; row < starRows; row++) {
    const isEvenRow = row % 2 === 0;
    const colsInRow = isEvenRow ? 6 : 5;
    const xOffset = isEvenRow ? xStep : xStep * 2;
    
    for (let col = 0; col < colsInRow; col++) {
      stars.push(
        <div
          key={`star-${row}-${col}`}
          style={{
            position: "absolute",
            left: xOffset + col * (xStep * 2) - (stripeHeight * 0.25), // center roughly
            top: yStep * (row + 1) - (stripeHeight * 0.25),
          }}
        >
          <StarIcon size={stripeHeight * 0.6} color="#FFFFFF" />
        </div>
      );
    }
  }

  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        backgroundColor: "white",
        border: "4px solid #000000", // Cartoon outline
        boxSizing: "border-box",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Stripes */}
      {Array.from({ length: 13 }).map((_, i) => (
        <div
          key={i}
          style={{
            position: "absolute",
            top: i * stripeHeight,
            left: 0,
            width: "100%",
            height: stripeHeight,
            backgroundColor: i % 2 === 0 ? "#FF4444" : "#FFFFFF",
            borderBottom: i < 12 ? "1px solid rgba(0,0,0,0.1)" : "none",
          }}
        />
      ))}

      {/* Blue Field */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: blueWidth,
          height: blueHeight,
          backgroundColor: "#0044CC",
          borderRight: "2px solid #000000",
          borderBottom: "2px solid #000000",
        }}
      >
        {stars}
      </div>
    </div>
  );
};

const CartoonFlag: React.FC<CartoonFlagProps> = ({
  backgroundColor = "#87CEEB", // Sky blue default
  transparentBackground = false,
  durationInSeconds = 10,
  flagScale = 1,
  waveSpeed = 4,
  waveAmplitude = 15,
  poleColor = "#C0C0C0",
}) => {
  // Load fonts (even if unused, required by protocol)
  useFontLoader(["Fredoka One"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color parsing
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Dimensions
  const flagWidth = 500 * flagScale;
  const flagHeight = 300 * flagScale;
  const poleWidth = 20 * flagScale;
  const poleHeight = height * 0.8;
  
  // Animation: Pole Entry
  const poleEntrance = spring({
    frame,
    fps,
    config: { damping: 12 },
    from: height,
    to: height - poleHeight - 50,
  });

  const poleTop = poleEntrance;

  // Animation: Flag Wave (Slicing technique)
  const sliceCount = 20;
  const sliceWidth = flagWidth / sliceCount;

  // Flag unfurl animation
  const unfurl = spring({
    frame: frame - 15, // start slightly after pole
    fps,
    config: { damping: 15, stiffness: 80 },
    from: 0,
    to: 1,
  });

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      <div
        style={{
          position: "absolute",
          left: width / 2 - flagWidth / 2,
          top: poleTop,
          width: flagWidth + poleWidth,
          height: poleHeight,
        }}
      >
        {/* Pole */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: poleWidth,
            height: poleHeight,
            backgroundColor: poleColor,
            border: "3px solid #000000",
            borderRadius: "10px",
            zIndex: 10,
          }}
        >
          {/* Knob on top */}
          <div
            style={{
              position: "absolute",
              top: -20 * flagScale,
              left: -5 * flagScale,
              width: 30 * flagScale,
              height: 30 * flagScale,
              borderRadius: "50%",
              backgroundColor: "#FFD700", // Gold
              border: "3px solid #000000",
            }}
          />
        </div>

        {/* Flag Container */}
        <div
          style={{
            position: "absolute",
            left: poleWidth - 4, // Overlap slightly
            top: 10,
            width: flagWidth,
            height: flagHeight,
            transformOrigin: "left center",
            transform: `scaleX(${unfurl})`,
          }}
        >
          {/* Slices for Wave Effect */}
          {Array.from({ length: sliceCount }).map((_, i) => {
            // Calculate wave offset
            // Wave moves from left to right, so phase depends on index
            const offset = i / sliceCount; // 0 to 1
            const wave = Math.sin((frame * waveSpeed / 10) - (offset * Math.PI * 2)) * (waveAmplitude * offset); 
            // * offset ensures the side attached to pole doesn't move much

            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: i * sliceWidth,
                  top: wave, // Apply wave displacement
                  width: sliceWidth + 1, // +1 to prevent gaps
                  height: flagHeight,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    left: -(i * sliceWidth),
                    top: 0,
                    width: flagWidth,
                    height: flagHeight,
                  }}
                >
                  <FlagGraphic width={flagWidth} height={flagHeight} />
                </div>
                
                {/* Gloss overlay for 3D cartoon effect */}
                 <div
                  style={{
                    position: "absolute",
                    left: 0,
                    top: 0,
                    width: "100%",
                    height: "100%",
                    backgroundColor: "black",
                    opacity: interpolate(
                        Math.sin((frame * waveSpeed / 10) - (offset * Math.PI * 2)),
                        [-1, 1],
                        [0, 0.15]
                    ),
                    pointerEvents: "none"
                  }}
                />
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CartoonFlag;